describe("keyFingerprint", () => {
  test.each(VECTORS)("matches GnuPG for $name", async ({ attribute, pubkey, date, fingerprint }) => {
    const fp = await keyFingerprint(hex(attribute), pubkey, date);
    expect(fp.toString("hex")).toBe(fingerprint);
  });

  test("ignores the import format byte of the attributes", async () => {
    const { attribute, pubkey, date, fingerprint } = VECTORS.find((v) => v.name === "ECDSA NIST P-256");
    const fp = await keyFingerprint(hex(attribute + "ff"), pubkey, date);
    expect(fp.toString("hex")).toBe(fingerprint);
  });

  test("depends on the creation date", async () => {
    const { attribute, pubkey, date, fingerprint } = VECTORS[0];
    const fp = await keyFingerprint(hex(attribute), pubkey, date + 1);
    expect(fp.toString("hex")).not.toBe(fingerprint);
  });

  test.each([
    ["no attributes", "", { 0x86: hex("00") }],
    ["an unknown algorithm", "642a8648ce3d030107", { 0x86: hex("00") }],
    ["an unknown curve", "1301020304", { 0x86: hex("00") }],
    ["a missing point", "132a8648ce3d030107", {}],
    ["a missing RSA exponent", "010800002001", { 0x81: hex("c0ffee") }],
  ])("is not computed for %s", async (_, attribute, pubkey) => {
    expect(await keyFingerprint(hex(attribute), pubkey, 0)).toBe(null);
  });
});
